CODES={'NOT_RUN':'Проверка ещё не выполнялась','RUNNING':'Выполняется','ID_CONFIG_OK':'Идентификатор и конфигурация совпали','IMU_ID_CONFIG':'Ошибка обмена, ID или конфигурации IMU','BARO_ID_CONFIG':'Ошибка ID, готовности или CRC PROM барометра','IMU_STREAM_OK':'Данные IMU обновляются','BARO_STREAM_OK':'Данные барометра обновляются','EXTERNAL_REQUIRED':'Выберите отдельный тест; требуется действие или оборудование','OPERATOR_CONFIRM':'Сигнал завершён. Подтвердите наблюдение','VISUAL_CONFIRM':'Проверьте сетку и текст на видеомониторе','SD_INSERT':'Вставьте отформатированную SD-карту','SD_MOUNT_OK':'Файловая система доступна; запись проверяется отдельно','SD_RW_OK':'Тестовый файл записан, прочитан и удалён','NO_FLASH_SCRATCH':'Безопасная область для записи Flash не выделена','SELFTEST_NOT_IMPLEMENTED':'Возбуждение self-test и сравнение с OTP пока не реализованы','OPERATOR_CONFIRMED':'Подтверждено оператором','OPERATOR_REJECTED':'Оператор не подтвердил результат','USB_PC_REQUIRED':'Для проверки подключите ПК','USB_FRAMED_OK':'Корректный обмен кадрами USB','CANCELLED':'Остановлено оператором','NOT_APPLICABLE':'Узел отсутствует в этом профиле','EXTERNAL_NOT_AUTOMATED':'Электрическая проверка этого тракта требует внешней методики','ANALOG_REFERENCE_REQUIRED':'Сравните показания с эталонным источником или измерителем','REST_CONDITIONS':'Не выполнены условия покоя; это не доказательство отказа','MOTION_OBSERVED':'Зафиксирована реакция на поворот','MOVE_BOARD':'Поверните плату вокруг осей','DEMO_SIMULATED':'Демонстрационные данные; физическая плата не проверялась'}
def instructions(test,profile=None):
    if test.startswith('pwm'):
        return 'Снимите пропеллеры и отключите двигатели, серво и опасные нагрузки. Подключите осциллограф между выбранным сигнальным выводом и GND. Тест выдаёт PWM 50 Гц, высокий импульс 1000 мкс, не более 2 с. Безопасность сигнала и электрический тракт подтверждает оператор. DShot этим тестом не проверяется.'
    if test=='rcin.frames':return 'Подключите совместимый приёмник или генератор с логическими уровнями 3,3 В к выделенному RCIN и общий GND. Нужны минимум три декодированных кадра и не менее четырёх каналов в диапазоне 750–2250 мкс. Отдельно проверьте failsafe при отключении приёмника.'
    if test.startswith('uart'):
        return 'Отключите периферию. Соедините TX и RX только выбранного порта. Сигналы 3,3 В, общий GND; питание не замыкать. Проверка отправит 16 байт при 115200 8N1. Отсутствие перемычки означает неполную проверку. RTS/CTS требуют отдельного анализатора. Номер UART здесь соответствует SERIALn из HWDEF.'
    if test.startswith('can'):
        return 'Нужны CAN-анализатор, общий GND и согласованная линия. Тест временно включает выбранный трансивер и передаёт classic CAN 500 кбит/с: CAN1 ID 0x6A0, CAN2 ID 0x6A1, восемь байт. Ответчик должен вернуть эти же восемь байт с ID 0x6B0 или 0x6B1 соответственно. Ожидание 2 с; затем управляемый трансивер возвращается в silent. Отсутствие ответа оставляет проверку неполной.'
    if test=='osd.video':return 'Подключите аналоговую камеру и видеомонитор, обеспечьте их штатное питание. На изображении должна появиться рамка и MYBOX DIAGNOSTIC. После запуска отдельно подтвердите наблюдение. Регистры OSD сами по себе не доказывают видеовыход.'
    if test=='sd.write':return 'Вставьте FAT-карту со свободным местом. Будет создан только новый файл MYBOX-DIAG-SCRATCH.bin через эксклюзивное создание, записано 512 байт, выполнены синхронизация, чтение, сравнение и удаление. Существующий одноимённый файл не перезаписывается. Скорость в отчёте — сквозная для этой операции, не паспортная скорость SD.'
    if '.rest' in test:return 'Положите плату неподвижно на 1,5 с. Скрининг: норма ускорения 9,80665 ± 1,5 м/с² и максимальная угловая скорость менее 5 °/с. Движение и смещение нуля дают предупреждение.'
    if '.motion' in test:return 'Поверните плату вокруг осей в течение 1,5 с. Порог наблюдаемой реакции: 30 °/с. Отсутствие движения означает необходимость повторить действие.'
    if test=='imu.compare':return 'Держите плату неподвижно. Сравниваются ускорения двух IMU в осях аппаратного профиля; ROTATION_NONE задана в профиле. Расхождение более 3 м/с² даёт предупреждение; вибрации и ориентация влияют на результат.'
    if test.startswith('adc.'):
        return 'Подключите штатный источник/датчик и эталонный мультиметр. Показаны исходный АЦП, напряжение АЦП, коэффициент и пересчитанное значение. Без внешнего сигнала статус не считается отказом. ADC pressure — напряжение после коэффициента 2, без выдуманного перевода в Паскали.'
    if test=='mag.external':return 'На плате нет встроенного магнитометра. Требуются конкретная внешняя модель, адрес и ориентация. Автоматического драйвера внешнего компаса в текущем приложении нет; абсолютный курс не вычисляется.'
    if test=='heater.external':return 'Нагреватель оставлен выключенным. Нужны подтверждённый монтаж резисторов, внешний термометр и измерение питания; активный нагрев в текущем комплекте не реализован.'
    if test=='safety.button':return 'Запустите тест и нажмите/отпустите кнопку safety в течение 5 с. Проверяется изменение уровня PE3.'
    if test in ('led.visual','safety.led','buzzer.audio'):return 'Наблюдайте выбранный светодиод или слушайте зуммер во время ограниченного по времени теста. Затем подтвердите результат отдельной кнопкой.'
    return 'Автоматическая проверка выполняет только указанную функцию. Полный охват и ограничения описаны в инструкции и таблице покрытия. Неисправность одного узла не должна останавливать остальные.'
